//돋보기 기능
var nowZoom = 100;
var nowZoom_f = 1;
var zoomcontrol = {		
	zoomout : function(){
		nowZoom = nowZoom - 10;
		nowZoom_f /= 1.2;
		if(nowZoom <= 70) nowZoom = 70;
		zoomcontrol.zooms();
		return false;
	},
	zoomin : function(){
		nowZoom = nowZoom + 10;
		nowZoom_f *= 1.2;
		if(nowZoom >= 500) nowZoom = 500;
		zoomcontrol.zooms();
		return false;
	},
	zoomreset : function(){
		nowZoom = 100; 
		nowZoom_f = 1;
		zoomcontrol.zooms();
		return false;
	},
	zooms : function(){
		document.body.style.zoom = nowZoom + '%';		
		document.body.style.MozTransform = 'scale('+nowZoom_f+')';  // Mozilla(firefox)
		document.body.style.MozTransformOrigin = '0 0';
		document.body.style.OTransform = 'scale('+nowZoom_f+')';  // Opera
		document.body.style.OTransformOrigin = '0 0';		
		if(nowZoom == 70){
			alert ("30% 축소 되었습니다. 더 이상 축소할 수 없습니다.");
		}			
		if(nowZoom == 500){
			alert ("500% 확대 되었습니다. 더 이상 확대할 수 없습니다.");
		}
	}		
}

function fSearch(pageIndex)
{
	$("#searchFrm").attr("action","/etc/search01/list.do").submit();
}
