function fDownLoad(folder, fileCode, fileName, gigwan_code) {
	//ncom.file.download(folder, fileCode, fileName);
	if(gigwan_code == "1"){
		location.href='https://yscwf.or.kr/nc_client/file/download.jsp?_folder=/'+folder+'/&_file_p='+fileCode+'&_file_l='+fileName;
	}else if(gigwan_code == "2"){
		location.href='https://yscrc.or.kr/nc_client/file/download.jsp?_folder=/'+folder+'/&_file_p='+fileCode+'&_file_l='+fileName;
	}else if(gigwan_code == "3"){
		location.href='https://uswelfare.or.kr/nc_client/file/download.jsp?_folder=/'+folder+'/&_file_p='+fileCode+'&_file_l='+fileName;
	}else if(gigwan_code == "4"){
		location.href='https://yscswc.or.kr/nc_client/file/download.jsp?_folder=/'+folder+'/&_file_p='+fileCode+'&_file_l='+fileName;
	}else if(gigwan_code == "5"){
		location.href='https://usswc.or.kr/nc_client/file/download.jsp?_folder=/'+folder+'/&_file_p='+fileCode+'&_file_l='+fileName;
	}else if(gigwan_code == "7"){
		location.href='https://yscwf.or.kr/nc_client/file/download.jsp?_folder=/'+folder+'/&_file_p='+fileCode+'&_file_l='+fileName;
	}
}

function fDownLoadsnbr(idx) {
	location.href = 'https://snbr.or.kr/AttachUtil/employdownload.do?file_idx='+idx;
}
